  fun ms' => exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 P) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
                  t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(P, P + roundup4k size); (bv_unsigned sp - 48, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' P [CB (Z.to_nat (roundup4k size)) (repeat (Z_to_bv 8 0) (Z.to_nat (roundup4k size)))]
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ mm_gcells m'.

Lemma mod_B_spec : forall ra sp gp tp t0 t1 t2 a6 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (s0o s1o s2o : word) (P size : Z) (name : word) (lo : Z),
  (0 < P)%Z -> (0 < size)%Z -> (P + roundup4k size <= lo)%Z ->
  hide (P + roundup4k size <= img_hull_lo \/ img_hull_hi <= P)%Z ->
  mod_frame m sp ra s0o s1o s2o ->
  mm_gcells m ->
  stk asegs m lo (bv_unsigned sp - 48) -> (kHighShadowEnd + 8 <= lo)%Z -> (lo <= bv_unsigned sp - 48)%Z -> (bv_unsigned sp <= 2^47)%Z ->
  mem_inv asegs m ->
  evt asegs (mod_B_post ra sp gp tp s0o s1o s2o s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P size lo m)
    (nret (MSsvc (mod_regs ra sp gp tp t0 t1 t2 a6 size name s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
                 (Z_to_bv 64 sec_mmap_ecall) (Z_to_bv 64 222) fc None m (seg_rom asegs))
          (mkEffect (Z_to_bv 64 P) [] [(Z_to_bv 64 P, Z_to_bv 64 (roundup4k size))])).
Proof.
